/* Screenshots and end-to-end checks against the throw-away HA of setup_ha.py.
 *
 * Usage: node shoot_ha.mjs <url> <out_dir>
 * Logs in as the demo user, links a few breakers to fake power sensors (the
 * demo house has no Shelly), installs the dashboard generated by the
 * integration itself, then captures it in light and dark themes.
 */
import { chromium } from 'playwright';
import fs from 'node:fs';

const [, , HA, OUT = '/tmp/shots'] = process.argv;
fs.mkdirSync(OUT, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Fake live power for a few circuits of the fictional demo board.
const CIRCUITS = {
  'T1-R1-1': ['sensor.demo_eclairage_sejour', 42],
  'T1-R1-2': ['sensor.demo_eclairage_chambres', 18],
  'T1-R1-4': ['sensor.demo_prises_sejour', 96],
  'T1-R1-7': ['sensor.demo_lave_linge', 1120],
  'T1-R2-1': ['sensor.demo_plaque', 0],
  'T1-R2-3': ['sensor.demo_lave_vaisselle', 3],
};

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1, locale: 'fr-FR' });
const logs = [];
const t0 = Date.now();
const stamp = () => ((Date.now() - t0) / 1000).toFixed(1);
page.on('console', (m) => logs.push(`${stamp()} ${m.type()}: ${m.text()}`));
page.on('request', (r) => { if (r.url().includes('home-infra-map-card')) logs.push(`${stamp()} REQ ${r.url()}`); });
page.on('pageerror', (e) => logs.push(`${stamp()} PAGEERROR ${e.message}`));
page.on('websocket', (ws) => {
  ws.on('framesent', (f) => { if (String(f.payload).includes('lovelace/resources')) logs.push(`${stamp()} WS> ${f.payload}`); });
  ws.on('framereceived', (f) => { if (String(f.payload).includes('home-infra-map-card.js')) logs.push(`${stamp()} WS< ${String(f.payload).slice(0, 300)}`); });
});
page.on('framenavigated', (f) => { if (f === page.mainFrame()) logs.push(`${stamp()} NAV ${f.url()}`); });

await page.goto(HA, { waitUntil: 'domcontentloaded' });
await page.locator('input[autocomplete="username"]').first().waitFor({ timeout: 60000 });
await page.locator('input[autocomplete="username"]').first().fill('demo');
await page.locator('input[type="password"]').first().fill('demo1234demo');
await page.keyboard.press('Enter');
await page.waitForFunction(() => window.hassConnection !== undefined, null, { timeout: 60000 });
await sleep(2500);

const result = await page.evaluate(async (circuits) => {
  const conn = (await window.hassConnection).conn;
  const call = (msg) => conn.sendMessagePromise(msg);
  const got = await call({ type: 'home_infra_map/get' });
  const boards = structuredClone(got.model.boards);
  for (const row of boards[0].rows) {
    for (const m of row.modules) {
      const c = circuits[m.ref];
      if (c) m.power_entity_id = c[0];
    }
  }
  await call({ type: 'home_infra_map/save', section: 'boards', data: boards, expected_revision: got.section_revisions.boards });
  const dash = await call({ type: 'home_infra_map/generate_dashboard' });
  return { dash: dash.yaml, entities: Object.keys(got.entities).length };
}, CIRCUITS);
console.log('entities owners:', result.entities);

// fake power sensors through the REST API (same token as the page)
const token = await page.evaluate(async () => (await window.hassConnection).auth.data.access_token);
for (const [entity, watts] of Object.values(CIRCUITS)) {
  await fetch(`${HA}/api/states/${entity}`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ state: String(watts), attributes: { unit_of_measurement: 'W', device_class: 'power', state_class: 'measurement' } }),
  });
}

// install the dashboard generated by the integration (parsed by the YAML of the page? no: build cards directly)
await page.evaluate(async () => {
  const conn = (await window.hassConnection).conn;
  const got = await conn.sendMessagePromise({ type: 'home_infra_map/get' });
  const board = got.model.boards[0].id;
  // HA 2026.10: /lovelace redirects to the new Overview panel; use a dashboard of our own.
  const dashboards = await conn.sendMessagePromise({ type: 'lovelace/dashboards/list' });
  if (!dashboards.some((d) => d.url_path === 'maison-demo')) {
    await conn.sendMessagePromise({
      type: 'lovelace/dashboards/create', url_path: 'maison-demo', title: 'Maison', icon: 'mdi:home-lightning-bolt-outline',
      mode: 'storage', require_admin: false, show_in_sidebar: true,
    });
  }
  await conn.sendMessagePromise({
    type: 'lovelace/config/save', url_path: 'maison-demo',
    config: { views: [
      { title: 'Électricité', path: 'elec', type: 'panel', cards: [{ type: 'custom:home-infra-map-card', view: 'electricity', board }] },
      { title: 'Réseau', path: 'net', type: 'panel', cards: [{ type: 'custom:home-infra-map-card', view: 'network', network_view: 'topology' }] },
    ] },
  });
});
fs.writeFileSync(`${OUT}/generated-dashboard.yaml`, result.dash);

async function capture(path, name, theme) {
  await page.goto(`${HA}/maison-demo/${path}`, { waitUntil: 'domcontentloaded' });
  if (theme) {
    await page.evaluate(async (dark) => {
      const ha = document.querySelector('home-assistant');
      ha?._applyTheme?.(dark);
      ha?.dispatchEvent(new CustomEvent('settheme', { detail: { dark }, bubbles: true, composed: true }));
    }, theme === 'dark');
  }
  // wait for the card to be defined *and* rendered somewhere in the shadow DOM
  await page.waitForFunction(() => {
    const find = (n) => { if (!n) return null; if (n.localName === 'home-infra-map-card') return n;
      for (const c of [...(n.shadowRoot?.children ?? []), ...(n.children ?? [])]) { const f = find(c); if (f) return f; } return null; };
    const card = find(document.body);
    return !!customElements.get('home-infra-map-card') && card?.shadowRoot?.querySelector('ha-card');
  }, null, { timeout: 45000, polling: 500 }).catch(() => console.log('timeout waiting for the card'));
  await sleep(2500);
  const errorCards = await page.evaluate(() => {
    const out = [];
    const walk = (n) => { if (!n) return; if (String(n.localName).startsWith('hui-error')) out.push(JSON.stringify(n._config ?? n.config ?? n.localName)); [...(n.shadowRoot?.children ?? []), ...(n.children ?? [])].forEach(walk); };
    walk(document.body); return out;
  });
  const defined = await page.evaluate(() => !!customElements.get('home-infra-map-card'));
  console.log(name, { defined, errorCards });
  await page.screenshot({ path: `${OUT}/${name}.png` });
  return { defined, errorCards };
}

const checks = [];
checks.push(await capture('elec', 'ha-electricite'));
checks.push(await capture('net', 'ha-reseau'));
await browser.close();
fs.writeFileSync(`${OUT}/console.log`, logs.join('\n'));
const ok = checks.every((c) => c.defined && c.errorCards.length === 0);
console.log(ok ? 'E2E OK' : 'E2E FAILED');
process.exit(ok ? 0 : 1);
